from lib import *
S = SS('w15')
steps = [
    step("往 127.0.0.1 一个没人监听的 UDP 端口发数据报,本机内核回 ICMP 类型 3 代码 3(端口不可达)。抓到 2 个 UDP 包和 2 个差错报文(我发了两次),每个差错报文 IP 总长 56 = 20 字节 IP 头 + 8 字节 ICMP 头 + 引用 28 字节,来自 127.0.0.1。引用的 28 字节是原包的 IP 头加 UDP 头(原包共 45 字节,17 字节载荷没有被引用):前 26 字节与原包逐字节相同,最后 2 字节(UDP 校验和字段)原包里抓到 0xfe2c,引用里是 0x0000。应用这一侧:没有 connect 的 UDP 套接字 sendto 后 recvfrom 没有任何错误,只是超时;connect 过的套接字 send 后 recv 得到 ConnectionRefusedError [Errno 61]。ICMP 差错里引用了原包头,内核就是靠引用的地址和端口找到出错的套接字,而没有 connect 的套接字没有被通知。", t=tl(S(1)), mark=lidx(S(1), 'ICMP 类型 3(目的不可达)代码 3', '应用这一侧'), done=lidx(S(1), '抓到 2 个 UDP 包', '引用的 28 字节', '所以 UDP 想知道'), kv=KV([['ICMP', '类型 3 代码 3,IP 总长 56'], ['引用', '原包 IP 头 + UDP 头 = 28 字节'], ['connect 过的 UDP', 'recv → Connection refused'], ['没 connect 的 UDP', '没有错误,只是超时']], ['connect 过的 UDP'])),
    step("TCP 发到没人监听的端口,拒绝用的是 RST,不是 ICMP。lo0 上 connect 一个关闭的端口,0.27 ms 就报 Connection refused,只有 SYN 和 RST 两个包,ICMP 包 0 个。默认网关的 81 端口也是 RST 拒绝,但 connect 用了 1005 ms:线上第一个 SYN 带 ECN 标志(SEW),3.023 ms 收到 RST;1001 ms 时 macOS 又发一个 SYN,这次去掉了 ECN 标志(S),再被 RST 才报错——重发是不是 ECN 协商失败后的回退,没有进一步验证。公网某主机的 81 端口完全没有回应:3 秒内发了 3 个 SYN(0、1000.982、2002.020 ms),收到 0 个包,connect 一直等到 3001 ms 超时。对照同一主机的 80 端口(有服务)连上用了 180~237 ms。被拒绝是快速失败,被丢弃只能等超时。", t=tl(S(2)), mark=lidx(S(2), 'SEW', 'Flags [S]', '公网主机 81 端口', '公网某主机的 81 端口'), done=lidx(S(2), 'lo0 上 connect', '其中 ICMP 包', '默认网关的 81 端口', '公网某主机的 80 端口'), b=bars([['lo0 关闭端口 · 拒绝', 0.27, '0.27 ms'], ['网关 81 端口 · 拒绝(重发一次 SYN)', 1005, '1005 ms'], ['公网 81 端口 · 丢弃', 3001, '3001 ms 超时'], ['公网 80 端口 · 有服务', 192, '约 192 ms']], 3001, mark=[2], done=[0, 1, 3]), kv=KV([['TCP 拒绝', 'RST,不是 ICMP'], ['网关的拒绝', '第二个 SYN 才报错,共 1005 ms'], ['防火墙丢弃', '3 个 SYN 无回应,3001 ms 超时']], ['防火墙丢弃'])),
    step("往 12 个不同的目的地发 UDP 数据报(端口 33435,没人监听),只有 4 个收到了差错报文:远端私有地址 10.x 由本机默认网关回 类型 3 代码 1(主机不可达),IP 总长 68;三台公网主机回 类型 3 代码 3(端口不可达)——都是目的地自己回的,总长 56 / 68 / 68。其余 8 个(默认网关、172.31.x、100.64.x、169.254.x、保留地址 240.0.0.1、三个文档地址)一个差错也没有。默认网关在这一轮里没回,再单独连发 10 个(间隔 1 s)却收到 7 个类型 3 代码 3——网关不是每次都回。没有回复不等于没有问题:发送方既不知道包到了没有,也不知道为什么没到。", t=tl(S(3)), mark=lidx(S(3), '主机不可达', '端口不可达', '默认网关再单独试'), done=lidx(S(3), '没有收到任何 ICMP 差错', '12 个目的地里'), b=bars([['12 个目的地里收到差错', 4, '4'], ['没有任何回应', 8, '8'], ['网关 10 个里回了', 7, '7 / 10']], 12, mark=[1], done=[0, 2]), kv=KV([['3/1 主机不可达', '由网关代回(远端私有地址)'], ['3/3 端口不可达', '由目的主机自己回'], ['不回', '不能区分丢了、被禁、还是限速'], ['网关', '10 个里回了 7 个']], ['不回'])),
    step("差错报文引用原包的长度因设备而异。同样 40 字节的 UDP 探测,TTL=2、3 的路由器回 Time Exceeded,IP 总长 68,引用 40 字节(整个原包,含载荷);TTL=4、10、11 的回 56 字节,引用 28 字节(IP 头 + 8 字节 UDP 头);第三节里三台公网主机引用的分别是 28、40、40 字节;本机内核回端口不可达引用 28 字节。能比较的字段都和原包一致:IP 头里的版本/长度/标识/协议/源/目的相同,UDP 头相同,40 字节的还包括载荷相同。规范要求至少引用 IP 头加 8 字节(28 字节),traceroute 就靠这 8 字节里的端口对应探测。", t=tl(S(4)), mark=lidx(S(4), 'TTL=2 ', 'TTL=3 ', 'TTL=4 ', 'TTL=10', 'TTL=11'), done=lidx(S(4), '各种 (类型', '规范要求', '对照第一节'), b=bars([['TTL=2、3 的路由器 · 引用', 40, '40 字节'], ['TTL=4、10、11 的路由器 · 引用', 28, '28 字节'], ['本机内核 · 引用', 28, '28 字节']], 40, mark=[0], done=[1, 2]), kv=KV([['最少', 'IP 头 + 8 字节 = 28 字节'], ['有的设备', '引用整个 40 字节原包'], ['用途', '用端口对应哪个探测 / 套接字']], ['最少'])),
    step("不对广播回差错:往子网广播地址的 33435 端口发 5 个 UDP 数据报,整个网段没有一台设备回 ICMP(0 个、0 台);同样发给默认网关(单播)5 个,收到 3 个差错、来自 1 台设备。规范(RFC 1122 / 1812)要求不对发给广播 / 组播地址的数据报回 ICMP 差错,否则一个广播会引来整网的回复;也不对 ICMP 差错本身再回差错。这里只验证了第一条在本机所在网段的表现。", t=tl(S(5)), mark=lidx(S(5), '子网广播地址'), done=lidx(S(5), '默认网关(单播)', '规范'), b=bars([['发到广播地址 5 个 · 收到差错', 0, '0'], ['发到网关单播 5 个 · 收到差错', 3, '3']], 5, mark=[0], done=[1]), kv=KV([['发给广播', '没有任何差错回复'], ['发给单播', '网关回了 3 / 5'], ['规则', '不对广播回,不对差错再回差错']], ['发给广播'])),
]
A = mkartw('w15', 15, '网络协议,ICMP,差错报文,目的不可达,端口不可达,RST,真实验证,动画演示',
    '抓包看 ICMP 差错报文:UDP 端口不可达(类型 3/3)引用 28 字节原包,connect 过的 UDP 才能收到错误;TCP 用 RST 拒绝、网关拒绝要 1005 ms(SYN 重发一次)、防火墙丢弃要等 3001 ms 超时;12 个目的地只有 4 个回差错;引用长度 28 与 40 字节两种;广播不回差错。',
    '路由器和主机怎么告诉你“送不到”?ICMP 差错报文里放了什么?为什么 UDP 套接字有时收不到错误,TCP 被拒绝和被丢弃的体验差别这么大?这篇向 12 个不同的目的地发探测,抓下回来的每一个 ICMP 差错报文,逐字节核对它们引用的原包。',
    [('28 / 40 字节', '不同设备在 ICMP 差错里引用的原包长度:最少是 IP 头加 8 字节'), ('1005 ms 对 3001 ms', 'connect 被网关 RST 拒绝与被防火墙丢弃(无任何回应)各用的时间'), ('4 / 12', '往 12 个目的地发 UDP 探测,实际收到 ICMP 差错报文的目的地个数')],
    [('端口不可达', '<p>UDP 发到没人监听的端口,对方回 ICMP 类型 3 代码 3,里面引用原包的 IP 头和 UDP 头。只有 connect 过的 UDP 套接字能把它变成 ECONNREFUSED;没 connect 的套接字什么也不知道。</p>'),
     ('拒绝与丢弃', '<p>TCP 的拒绝是 RST,不用 ICMP。lo0 上 0.27 ms 就失败;网关的 RST 配合一次 SYN 重发共 1005 ms;防火墙丢弃则一直等到 3001 ms 超时,3 个 SYN 没有任何回应。</p>'),
     ('谁会回', '<p>12 个目的地里只有 4 个回了差错:远端私有地址由网关回主机不可达,公网主机自己回端口不可达。其余的什么也没回,发送方无法区分原因;网关自己也只回了 10 个里的 7 个。</p>'),
     ('引用多少', '<p>规范只要求引用 IP 头加 8 字节。实测路由器有的引用 28 字节,有的引用整个 40 字节原包;引用里的端口让发送方(如 traceroute、内核)对应到具体探测或套接字。</p>'),
     ('不对广播回', '<p>发往子网广播地址的包没有任何设备回差错,发往单个主机的则会回。这避免一个广播引来整网回复。</p>')],
    steps,
    [ENV_W + '。第一、二节的 lo0 部分在本机回环上抓包,其余在 en0 上抓包(dpkt 解析 ICMP 差错与引用的原包);默认网关与 MAC 做了遮盖,公网主机的地址不写出;网关 / 路由器是否回差错、回哪种每次运行并不完全一样(同一目的地不同轮次结果不同),文中为最后一次运行',
     '没有验证:协议不可达(代码 2)、网络不可达(代码 0)、被管理禁止(代码 9 / 10 / 13)这些代码(本机网络没有触发);ICMP 重定向与源抑制;IPv6 的 ICMPv6 差错(见 IPv6 部分);ICMP 差错限速的具体阈值(见 ICMP 限速一篇);网关重发 SYN 是否因为 ECN 回退'],
    'ICMP 差错')
